-- Mod-authored world wonder splash painting descriptions, cs_CZ overlay.
-- Baseline in CivVAccess_WonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_MISSING"] = "Pro tento div není k dispozici žádný popis."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_MOTHERLAND_STATUE"] =
    "Hra byla vydána bez obrazu tohoto divu, takže není co popisovat."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_ALHAMBRA"] =
    "Ze stínu štíhlého kamenného sloupu se otevírá nádvoří paláce s dlouhým zrcadlícím se bazénem, což je Myrtový dvůr v Alhambře. Bazén se táhne k podloubí z růžově zbarveného kamene, jehož oblouky se odrážejí v klidné vodě. Vzadu se v teplých barvách tyčí hranatá pevnostní věž proti modré obloze. Nízké zastřižené živé ploty lemují okraj vody, v popředí stojí květináč s rostlinou a podél slunných chodníků postávají a povídají si malé skupinky lidí v dlouhých rouchách. Nádvoří zalévá jasné odpolední slunce, tam, kde dopadá na dlažbu, je bílé. Pod sloupovím leží hluboký stín."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_ANGKOR_WAT"] =
    "V pozadí vyrůstá shluk stupňovitých věží ze šedého kamene, utvářených jako zavřená poupata lotosu, napůl zakrytých palmami pod horkou, bledou oblohou. Popředí patří slavnostnímu průvodu: šedý slon kráčí hustým davem, na krku mu sedí jezdec a na hřbetě nese sedadlo s baldachýnem, zastíněné vysokým červenooranžovým slunečníkem. Dav se tlačí ze všech stran, v bílých, šafránových a švestkově fialových rouchách, hlavy mají ovázané, ramena odkrytá a každá tvář se otáčí za slonem, který míjí. Scéna je spálená sluncem a zaprášená, kámen je chladně zelenošedý proti teplé pleti a látkám dole."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_BIG_BEN"] =
    "Gotická hodinová věž stojí v noci na konci Westminsterského mostu, její čtyřstranné hodiny nedaleko vrcholu září jantarově. Nad hodinami se špice věže ztrácí v sytě modré obloze. Doleva se táhne dlouhé průčelí londýnského Parlamentu, jehož okna a kamenné prvky osvětlují reflektory teplým zlatem. Na jeho vzdáleném konci se zvedají věže s věžičkami. Popředím přechází most s řadou svítících lamp na sloupech. Několik kočárů a postav vypadá na vozovce drobně a tmavě. Celá scéna je namalována v nočních modrých tónech proti zlaté barvě lamp a osvětleného kamene."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_BOROBUDUR"] =
    "Stupňovitá pyramida ze šedého sopečného kamene vyrůstá z džungle jako terasovitý pahorek, její horní patra jsou obklopena malými zvonovitými stúpami. Větší stúpa korunuje vrchol. Z nižších teras rostou palmy a les se tiskne těsně k úpatí. V popředí stoupá k chrámu po zastíněné džunglové stezce zástup mnichů v oranžových a červených rouchách a po zamlžené obloze nad nimi se rozlétají ptáci. Barevnost je mlhavě šedozelená a roucha jsou jediným výrazným barevným tónem."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_BRANDENBURG_GATE"] =
    "Široká klasicistní brána ze zvětralého pískovce stojí napříč zadní částí rušného městského náměstí, zvedá se na dvojicích řad mohutných sloupů a korunuje ji kvadriga, bronzová socha čtyřspřeží, která se tmavě rýsuje proti bledé zamračené obloze. Vpravo vybíhá nižší křídlo se sloupovím k okolním kamenným budovám. Náměstí před bránou je Berlín devatenáctého století: koňské povozy se kodrcají po dlažebních kostkách, jezdci a davy v dlouhých tmavých kabátech a cylindrech, vlevo se zvedá lampa. Barvy jsou střízlivé šedé a hnědé a světlo je ploché a rovnoměrné."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_BROADWAY"] =
    "Divadelní čtvrť v noci na počátku dvacátého století, ulice je mokrá od deště a lesknou se v ní odrazy světel. Osvětlené markýzy a nápisy se tlačí po obou stranách třídy, bílé a červené žárovky skládají názvy představení. Uprostřed bloku září jedno dlouhé jasné průčelí divadla. Davy v tmavých kabátech a kloboucích zaplňují chodníky a přelévají se do ulice mezi několik starých automobilů, všichni jsou malí proti vysokým tmavým kancelářským budovám, které se zvedají do noční oblohy. Barevnost tvoří sytá modročerná, protkaná kalužemi teplého bílého, červeného a žlutého elektrického světla."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_CN_TOWER"] =
    "Štíhlá betonová jehla se zvedá uprostřed panoramatu Toronta, nahoře se rozšiřuje v oblou vyhlídkovou kabinu a dál se zužuje v anténní hrot. Kolem ní se trhají bouřková oblaka a za věží touto mezerou proudí dolů sluneční paprsky, které zamlžují kancelářské budovy po obou stranách. Popředí tvoří zapuštěná rychlostní silnice plná dopravy, světla reflektorů a červená zadní světla září v šeru mezi betonovými svahy. Celá scéna je ocelově šedá a zlatá. Město je zpola ve stínu bouře, zpola v prorážejícím světle."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_CHICHEN_ITZA"] =
    "Uprostřed stojí stupňovitá pyramida El Castillo pod planoucí oranžovou oblohou, devět čtvercových stupňů stoupá k malému chrámu na vrcholu. Přímo po jejím průčelí vede široké schodiště. U levého okraje se zvedá druhý stupňovitý chrám a kouř se vine přes slunce, které visí nízko a rudé. Náměstí dole je plné davu Mayů, většina z nich stojí zády: holá ramena, péřové čelenky, zdvižené hole a kopí. Vpravo na kamenné plošině stojí hlouček bojovníků. Vše je ponořeno do rezavého a jantarového světla soumraku. Dav se rýsuje jako tmavá silueta proti zářícímu kameni."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_CRISTO_REDENTOR"] =
    "Obrovský Kristus z bledého kamene, viděný zezadu a shora, stojí na podstavci na vrcholu hory s doširoka rozpaženýma rukama nad zálivem pod sebou. Jeho záda v rouchu a natažené paže vyplňují blízký okraj obrazu, hlava je mírně skloněná dopředu. Za ním a hluboko dole se kolem vody rozkládá Rio de Janeiro v bílých závějích budov, ze zálivu mezi zelenými ostrovy a kotvícími loděmi vystupuje oblý hrb Cukrové homole. Opar zjemňuje dálku a město i moře zůstávají v bledě modrých a šedých tónech, zatímco ramena sochy zachycují denní světlo."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_COLOSSUS"] =
    "Bronzový obr stojí daleko na skalnatém ústí přístavu, jednu paži zdvihnutou, napůl rozpuštěný ve zlatavém oparu. Proti obloze barvy mosazi je spíše siluetou než sochou. Popředí patří moři: malá plachetnice se naklání k divákovi pod jedinou širokou plachtou, na zádi jsou vidět dva nebo tři námořníci. Další plachty jsou rozeseté po přístavu. Vpravo podél hladiny vedou nízké skály a voda má stejné teplé zlato jako obloha. Celý obraz má jedinou barvu, jantarové světlo a opar. Kolos jím prosvítá jako postava ve snu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_MOSQUE_OF_DJENNE"] =
    "V pozadí se táhne dlouhá hliněná zeď věží a špiček z nepálených cihel v sytě rudohnědé barvě. Její stěny se ježí prvky zvanými toron, řadami dřevěných trámů trčících ze zdí jako trny. Obloha za ní je hustá oranžovým prachem a kouřem, slunce se ztrácí v oparu. Celé popředí je trhový den: stříšky a přístřešky v červené a bílé, zvířata mezi stánky a hustý dav v pestrých rouchách, který se mezi nimi pohybuje. Vedro a prach sjednocují scénu a vše je namalováno v oranžových, rezavých a hnědých tónech."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_EIFFEL_TOWER"] =
    "Tmavá železná mříž nohou a nosníkových plošin vyplňuje levou horní část záběru, tak blízko, že vrchol je useknut okrajem obrazu. Pod ní je scéna z odpoledne belle époque na trávě: skupiny v dlouhých bílých šatech a tmavých oblecích piknikují na široké zelené louce, kolem nich jsou rozloženy slunečníky, sluneční klobouky a košíky. Uprostřed stojí žena v bílém. Za loukou protéká Seina a bledý kámen Paříže se táhne podél vzdáleného břehu pod měkkou šedou oblohou. Barevnost tvoří chladná zeleň a šeď. Bílé šaty zachycují to málo světla, které tu je."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_FORBIDDEN_PALACE"] =
    "Palácové síně s široce zakřivenými střechami ze zlatých tašek a sytě rudými zdmi stojí přes rozlehlé dlážděné nádvoří, viděné z vyvýšené mramorové terasy v popředí. Tmavá socha lva strážce se krčí na balustrádě terasy vlevo a podél schodů stojí postavy v rouchách. Dole na nádvoří stojí vojáci seřazení v těsném útvaru před hlavní síní, architektura kolem nich je nesrovnatelně větší. Bledé slunce visí v zamlžené jantarové obloze a celá scéna je zalita zaprášeným zlatem proti rudé barvě zdí."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GLOBE_THEATER"] =
    "Kulaté dřevěné divadlo, vidět je z jeviště uprostřed představení. Tři patra galerií se zakulacují kolem prostředního nádvoří a každé zábradlí je plné diváků. Dole na holé zemi se tísní stojící diváci, bledé moře tváří. Na jevišti hraje herec v tmavém kabátci scénu ke dvěma ženám v dlouhých šatech, jedna z nich ukazuje nataženou paží. Malovaná stříška střechy vybíhá vpravo nahoře na vyřezávaném sloupu. Z otevřeného nebe nad nádvořím dopadá měkké denní světlo. Dřevo má teplou krémovou a hnědou barvu a dav je kolem ostřeji nakreslených postav na jevišti naznačen bledě."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GREAT_FIREWALL"] =
    "Abstraktní digitální scéna bez jediné budovy, temný kyberprostor v zelených a černých tónech. Obrazem se táhnou široké zakřivené plochy jako valy z dat, jejich stěny jsou pokryté zářícími zelenými binárními číslicemi a po nich se jako provoz na dálnici v noci šmouhami míhají světelné stopy. Nahoře v šeru se vznášejí přízračné obrazovky a mřížky, které naznačují obvody a sledování. Celý obraz vypadá jako vnitřní svět počítače, zelené světlo luminoforu na černé."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GREAT_LIBRARY"] =
    "Monumentální klasická síň stojí před slunečným náměstím a mezi sloupy její dlouhé kolonády visí vysoké rudé prapory. Nad sloupy probíhá vyřezávaný vlys a široké schody se rozlévají dolů k dlažbě. Náměstí je vidět ze zastíněného sloupového předsálí v popředí: vlevo vyrůstá sloup, vpravo sedí na podstavci kamenná sfinga a v dálce za ní prosvítá bílá kupole. Učenci a občané v tógách a barevných rouchách se shromažďují na schodech i po celém náměstí, většinou stojí ve dvojicích a trojicích a rozmlouvají, zatímco jedna postava sedí o samotě se svitkem. Kámen je ve slunci teple krémový pod modrou oblohou pruhovanou mraky a prapory jsou nejsytější červenou na celém obraze."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GREAT_LIGHTHOUSE"] =
    "Vysoká světlá věž ze stupňovitě narůstajících pater stojí daleko vpravo, osvětlená trhlinou v bouři, na jejím vrcholu září maják. Zbytek obrazu tvoří rozbouřené moře: řada starověkých galér s hranatými plachtami v červených a bílých pruzích se namáhavě probíjí těžkými šedozelenými vlnami ke světlu, přídě mají vysoko zakřivené. Bílá pěna se tříští o trupy. Tmavé bouřkové mraky tlačí na celou scénu a obloha se otevírá jen kolem věže, jako by k ní lodě mířily. Plachty nesou jedinou teplou barvu na obraze z břidlicové šedi, pěny a deště."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GREAT_WALL"] =
    "Široký kamenný val vede od spodního okraje obrazu přímo vzhůru a přes hory, jeho cimbuřím zakončené parapety šplhají po hřebenech, až se zeď na nejvzdálenějších vrcholcích zúží v nitku. U prvního stoupání stojí hranatá dvoupatrová strážní věž s klenutými okny a malým krytým pavilonem nahoře. Trasa zdi jí prochází v oblouku. Hory jsou zvrásněné a zelené, křovinatá úbočí klesají do mlhy údolí za údolím. Nikde na zdi není vidět žádná postava. Světlo je chladné a čisté, šedý kámen proti sytě zelené pod bledou oblohou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_HAGIA_SOPHIA"] =
    "Velká kupolovitá bazilika korunuje panorama města v hodině zlatého světla, její široká střední kupole se zvedá z masy opěrných zdí a polokupolí. Ve čtyřech rozích stojí štíhlé minarety, stavba je vykreslena jako mešita, kterou se později stala. Kolem ní se střechy Istanbulu svažují dolů v hnědavých a šedých tónech, přerušované stromy, menšími kupolemi a vzdálenými věžemi, které se rozplývají v mlze. Záblesk vody a nízké kopce uzavírají dálku vlevo. Vše leží pod teplou jantarovou oblohou a silueta kupole je proti světlu tmavě zlatá."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_HANGING_GARDEN"] =
    "Zahradní dvůr leží uvnitř zdí z teplých pískovcových oblouků. Nad chodníky se zvedají palmy a zeleň se přelévá přes každý oblouk i římsu. Postavy v rouchách se procházejí a rozmlouvají ve dvojicích a trojicích po stinných cestách mezi záhony a nízkými stromky. Středním obloukem a nad zdí vystupuje na kopec bílé palácové město v naskládaných terasách a v dálce se leskne jako koruna zahrady. Všechno stojí v jasném slunci, sytě zelené listoví proti zlatému kameni a bledé obloze."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_HIMEJI_CASTLE"] =
    "Bílý hradní donjon se zvedá ze zalesněného kopce na horním okraji obrazu, patro za patrem světlých stěn pod zakřivenými šedými střechami. Menší bílé věžičky se tísní pod ním mezi stromy. Cesta k němu vede vesnicí s tmavými taškovými střechami a ve střední vzdálenosti ji přemosťuje brána s červeným rámem. Jízdní samurajové k ní jedou popředím a z jejich zad se zvedají vysoké rudé prapory. Pěší vojáci ve zbroji čekají vpravo u domů. Den je měkký a zamračený a celá scéna se skládá ze zeleni a šedi kolem bílého donjonu. Prapory jsou nejostřejší červenou na obraze."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_HUBBLE"] =
    "Dlouhý stříbrný válec obalený fóliovými panely se vznáší na oběžné dráze, výklopná clona je na bližším konci otevřená a odkrývá tmavý otvor optiky. Z jeho boků se rozpínají ploché solární panely v měděně zlatých rámech a u jeho boku pracuje astronaut ve skafandru, drobný vedle přístroje. Do pravého dolního rohu obrazu zasahuje část přistavené kosmické lodi. Za vším vyplňuje obraz Země, křivka modrého oceánu a bílých mraků, která se propadá do černého vesmíru. Barevnost tvoří stříbrná a zlatá proti modři Země."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_KREMLIN"] =
    "Nad Rudým náměstím padá sníh. Vpravo se táhne pevnostní zeď z tmavě červených cihel pod těžkou šedou zimní oblohou. Ze zavalitého stupňovitého bloku Leninova mauzolea, přisazeného ke zdi, vlaje rudá vlajka a dál vzadu se do šera zvedá vysoká věž s jehlancem tvaru strmého stanu. Davy v dlouhých tmavých kabátech a kožešinových čepicích táhnou pomalou frontou přes zasněžené náměstí, osamělé postavy se v popředí brodí sněhem zády k divákovi. Obraz je téměř jednobarevný, bílý sníh a uhlově šedá, cihly a vlajka tvoří jediné červené tóny."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_LEANING_TOWER"] =
    "Kulatá bílá zvonice se zvedá ze zeleného trávníku, patro za patrem ji obepínají otevřené mramorové arkády a nezaměnitelně se naklání doprava. Stojí jasně proti tmavé bouřkové obloze. U pravého okraje obrazu stojí světlý bok katedrály v Pise a nižší městské budovy v okrové barvě uzavírají zeleň vlevo. Měšťané a mniši v dlouhých hnědých a červených hábitech přecházejí trávník v rozptýlených průvodech, pod věží drobní. Světlo je divadelní: trhlina v mracích osvětluje bílý mramor jako reflektor, zatímco obloha za ním zůstává téměř černá."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_LOUVRE"] =
    "Šedý kamenný palác se táhne v pozadí, vysoký střední pavilon s vyřezávanou výzdobou a strmými břidlicovými mansardovými střechami a po obou stranách křídla. Malíři ho ukazují z doby, kdy byl královským palácem, dávno před moderní skleněnou pyramidou muzea. Vpředu leží formální zahrady: rovné trávníky protnuté štěrkovými cestami, mladé stromy a vlevo malá kašna vrhající vodu. Po chodnících jsou rozeseti chodci v oblečení devatenáctého století, ženy v dlouhých bílých šatech a muži v tmavých kabátech a cylindrech. Vpravo se spolu zastavuje dvojice. Den je měkký a perleťový. Všechno je šedý kámen a tlumená zeleň pod bledou oblohou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_MACHU_PICHU"] =
    "Kamenné město leží ve vysokém horském sedle, zemědělské terasy stoupají po svahu ke shlukům budov se štíty pod došky. Za ním strmý vrchol Huayna Picchu stoupá do mraků. Mlha visí nad okolními pohořími a údolí dole klesá do stínu. Na stezce v popředí se vzhůru k branám města probírá malá skupina s nákladními lamami, drobná proti terasám. Světlo přichází v bledých pruzích skrz počasí a vybírá teple hnědavé kamenné zdivo ze zeleně a šedi And."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_MAUSOLEUM_HALICARNASSUS"] =
    "Mohutný čtvercový podstavec z bílého mramoru, pruhovaný vytesanými vlysy, se zvedá k věnci sloupů na horním okraji obrazu. Tyčí se nad náměstím, kde na vysokých pilířích stojí sochy, mezi nimi postava v brnění a jezdec. Mezi dlažbami jsou vysazeny tmavé cypřiše. Dole se shromažďují postavy v bílých a červených rouchách, před památníkem docela malé. Den je jasný a čistý. Bílý mramor a nakupené bílé mraky stojí proti sytě modré obloze."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_NEUSCHWANSTEIN"] =
    "Bledý přízrak zámku stojí na zalesněném hřebeni, bílé zdi a seskupené věže napůl rozpuštěné v padajícím sněhu v levé horní části obrazu. Popředí tvoří cesta vzhůru k zámku: tmavý uzavřený kočár čeká v zatáčce, zatímco jezdci míjejí a stoupají do svahu a rozrývají sníh na cestě. Jedle poprášené sněhem lemují cestu a nad údolím dole se zavírají. Obraz je celý v zimní šedi a bělosti. Jezdci a kočár jsou na něm jediné tmavé tvary."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_NOTRE_DAME"] =
    "Gotická katedrála se zvedá ze středověké Paříže, vidíme ji shora. Její dvě hranaté věže, střední věžice a dlouhá loď s opěrnými pilíři se tyčí daleko nad všemi okolními střechami. Město se tiskne k jejím zdem v hustém předivu domů s lomenicemi a kouřících komínů a Seina se v popředí vine kolem nábřeží a malých člunů. Obloha je těžká a šedá, ale paprsky slunce se probíjejí skrz mraky a dopadají přímo na katedrálu, takže její kámen září zlatě, zatímco město zůstává v břidlicovém stínu. Obzor za střechami mizí ploše a bledě."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_ORACLE"] =
    "Kruhový chrám se sloupovím pod kamennou kupolí, tholos, stojí na mořském útesu na konci skalnatého mysu a pod ním se v útesu otevírá přirozený oblouk. Umělci umístili svatyni na pobřeží, nikoli na horský svah v Delfách. K ní se vine stezka kolem přílivových tůněk a stojících skal. V popředí se po stezce ve skupinkách ubírají poutníci v červených, modrých a bílých řízách a z obou stran je rámují tmavé borovice, které se sem naklánějí. Je chladný časný večer, s bledou, měsícem osvětlenou oblohou a šedozeleným mořem kolem teplého kamene svatyně."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PARTHENON"] =
    "Dlouhý dórský chrám stojí celý v horní části obrazu a jeho sloupořadí nese vytesaný a malovaný štít. Mramor má teplou zlatou barvu pod oblohou valících se šedých mraků. Od chrámu klesají široká schodiště přes záhony nízkých zelených keřů, vlevo stojí na podstavcích bronzové sochy. Po schodech sestupuje průvod Řeků v karmínových pláštích a uprostřed stojí osamělý hoplita tváří k divákovi, v přilbě s hřebenem a s kulatým štítem na paži. Červeň plášťů plane proti kameni a světlo má těžkou jasnost dne, který se chystá k bouři."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PENTAGON"] =
    "Letecký pohled na pětibokou budovu ústředí, jejíž soustředné pětiúhelníkové prstence ze světlého betonu a tmavé střechy se stupňovitě sbíhají dovnitř k zelenému nádvoří uprostřed. Kolem budovy se vinou silnice a parkoviště, dál se rozkládají trávníky a stromy s podzimním nádechem. Za ní protéká Potomac, přes který vedou mosty. Na protějším břehu leží v oparu hlavní město, bílý obelisk Washingtonova monumentu a kupole Kapitolu jsou malé na obzoru. Den je všední a šedý; nic v obraze nevyniká kromě tvaru budovy."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PETRA"] =
    "Divák stojí uvnitř Siqu, úzkého přístupového kaňonu, mezi růžovočervenými skalními stěnami, které se tyčí ve stínu po obou stranách obrazu. Mezeru vyplňuje plné slunce a v něm stojí Al-Khazneh, Pokladnice, průčelí vytesané přímo do útesu. Její dvě patra klasických sloupů a štítů se zvedají z růžového pískovce a uprostřed horního patra je kulatý pavilon. Cestovatelé k ní míří po písčitém dně kaňonu: v popředí se kývají dva jezdci na velbloudech a za nimi jdou postavy v řízách. Obraz je celý v teplých červených a stinných hnědých tónech, vytesané průčelí září na konci temného průchodu."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PORCELAIN_TOWER"] =
    "Vysoká pagoda se zvedá nad chrámovou zahradou, patro za patrem tmavých vyklenutých okrajů střech na štíhlém těle. Tyčí se nad taškovými střechami hal u své paty. Zahrada se rozprostírá v popředí kolem klidného rybníka: zastřižené borovice, vrby, kamenné lucerny a vytesaná socha lva na podstavci u levého okraje. Postavy v řízách se procházejí po štěrkových cestách ve dvojicích a trojicích a za věží se v mlžném oparu zvedají zalesněné kopce. Scéna je klidná a zelená, měkké denní světlo leží na vodě a pagoda stojí tmavá proti bledé obloze."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PRORA_RESORT"] =
    "Monolitický blok lázeňského komplexu se táhne podél pobřeží zdánlivě bez konce. Jeho světlé průčelí nese stále tytéž řady oken, táhne se po pláži a mizí směrem k obzoru. Nejvzdálenější úsek je dosud zahalen lešením. Na blízkém konci stojí velká kulatá budova ve tvaru bubnu, obklopená sloupy na tmavě červeném podstavci, a na její střeše vlaje červená vlajka. Dole je na pláži živo: koupající se a procházející lidé jsou drobně rozptýleni po písku a vpravo se valí šedozelené moře. Vysoké sluncem zalité mraky vyplňují oblohu nad jasným odpolednem u moře, krémový beton proti modré vodě."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PYRAMID"] =
    "Dvě velké pyramidy stojí bledě v pouštním oparu, ta bližší vyplňuje pravou horní část obrazu. Třetí stojí malá na obzoru. Sfinga se krčí mezi nimi ve střední dálce. Palmy stojí v řídké řadě podél písku a nízké zříceniny zdí a bloků lemují prohlubeň v popředí. Jezdec v červeném sedí na velbloudu vpravo dole a vlevo přechází přes písek malá karavana velbloudů s postavami kráčejícími vedle nich. Všechno je písčité, žlutohnědé a barvy kosti pod zamlženou bílou oblohou. Červený jezdec je jedinou ostrou barvou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_RED_FORT"] =
    "Pevnost z tmavě červeného pískovce je pod útokem: vysoké hradby a kulaté bašty vyplňují obraz, bílé kupolovité pavilony stojí podél valů, z říms roste tráva a z ohňů uvnitř stoupají sloupy černého kouře. Obránci se tísní na cimbuří nad bránou. V popředí tlačí k hradbám obrnění vojáci v oblých přilbách, kolem dřevěného katapultu a jeho obsluhy u levého okraje. Obraz je těžký červeným kamenem a kouřem a jedinou úlevou jsou bílé pavilony a pruh bledé oblohy."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_SISTINE_CHAPEL"] =
    "Obřad uvnitř kaple, viděný zprostřed shromážděných. Zadní stěna za oltářem je od podlahy ke stropu pokryta freskou Posledního soudu, vířením postav na modrém pozadí, a malované výjevy a závěsy lemují boční stěny pod vysokými obloukovými okny. Freskovaná klenba jen zasahuje do horního okraje obrazu. U oltáře osvětleného svíčkami slouží bíle oděné duchovenstvo, zatímco kardinálové v šarlatu zaplňují popředí a lavice podél stěn. Jejich červeň je v tlumeném interiéru nejsilnější barvou. Denní světlo, kterého je málo, dopadá šedě z oken na malované stěny."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_INTERNATIONAL_SPACE_STATION"] =
    "Příhradová stanice visí na oběžné dráze proti černi vesmíru: dlouhý střední nosník, přes který se křižují dvojice velkých modrošedých solárních křídel, a uprostřed něj se shlukuje řetězec bílých válcových modulů a spojovacích uzlů. Na blízkém konci řetězce modulů je přichycena kapsle a pod nosníkem se ploše rozevírají chladicí panely. Za ní se v hluboké modři zakřivuje Země, na její noční straně jasně září víry mraků. Nahoře v černi jsou roztroušeny hvězdy. Obraz je čistý a fotografický: bílý kov, modrá planeta a nikde žádné postavy."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_STATUE_OF_LIBERTY"] =
    "Postava v rouchu z mědi, zvětralé do bledozelené, stojí na kamenném podstavci vlevo od rušného přístavu, s paží s pochodní vztyčenou vysoko proti obloze s roztrhanými mraky. Kolem ní pluje zaoceánský parník z počátku dvacátého století s černým trupem a dvěma červenočernými komíny, z nichž se line uhelný kouř, zatímco po jeho boku se vlnobitím prodírají remorkéry. Panorama New Yorku leží nízko a v mlžném oparu přes vodu vpravo. Scéna je malována v mořských šedích a zeleních, kouř a mraky se mísí. Bledozelená socha je nejzřetelnějším tvarem ve všem tom kouři a mracích."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_STONEHENGE"] =
    "Kruh velkých stojících kamenů s překlady nahoře stojí v noci na tmavém vřesovišti a teple žhne od ohňů zapálených kdesi uvnitř, jako by probíhal obřad. Nad ním se hvězdnou oblohou řítí kometa. V zastíněném popředí vyčnívají z vřesoviště roztroušené odlehlé kameny a po planině je rozseto pár malých ohňů a slabé postavy. Všechno je v hluboké noční modři kromě jantarového světla, které se rozlévá u památníku."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_SYDNEY_OPERA_HOUSE"] =
    "Velké bílé střešní skořepiny ve tvaru plachet vyplňují zblízka pravou část obrazu a překrývají se proti jasně modré obloze. Pod nimi je vidět sklo a tmavé kamenné zdivo základny budovy. Hned za nimi kotví velká bílá výletní loď a štíhlá motorová jachta rozráží vlnky v popředí. Přes třpytivý přístav stojí daleko vlevo sydneyské věže. Den je jasný a čistý. Bílé střechy a bílé lodě vynikají na hluboké modrozelené vodě."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_TAJ_MAHAL"] =
    "Mauzoleum z bílého mramoru stojí čelem na konci své dlouhé zahrady, jeho velká střední kupole se nadouvá nad obloukovým výklenkem brány. Menší kupolové pavilony stojí po obou stranách velké kupole a na každém rohu terasy se zvedá minaret. Zahrada vede přímo k němu: úzký zrcadlící kanál uprostřed, po stranách dlážděné chodníky, řady tmavých cypřišů a nízké zelené záhony. Několik drobných postav v řízách kráčí po cestách. Obloha vzadu je jemný západ slunce broskvových a zlatých barev a mramor tu barvu přijímá, bílá přechází do krémové a růžové."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_TEMPLE_ARTEMIS"] =
    "Dlouhé mramorové sloupořadí pod vytesaným štítem korunuje vyvýšeninu v zadní části výjevu, před schody se zvedá socha jezdce a podél příchodu tmavě stojí cypřiše. Široká terasa vpředu je plná života: postavy v bílých tógách a barevných rouchách se procházejí a obchodují, vlevo si u košů dřepí prodavači a vpravo v popředí těsně míjejí zahalené ženy. Červený sloup rámuje pohled u levého okraje a daleko dole se svažuje zelená krajina údolí s řekou. Polední slunce pálí na bílý mramor a jasné látky pod modrou oblohou nakupenou mraky."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_STATUE_ZEUS"] =
    "Uvnitř chrámové haly trůnící bůh ze zlata a slonoviny se tyčí až ke stropu, vousatý a s odhalenou hrudí, s rouchem přes klín. Jedna ruka drží nad halou malou okřídlenou postavu Vítězství a druhá svírá vysoké žezlo. Jeho trůn je zlatě zdobený před stěnou teple červené barvy a řady sloupů se táhnou po obou stranách sálu a postranní lodě nechávají ve stínu. U úpatí sochy se shromažďují ctitelé v bledých rouchách, žádný z nich nedosáhne ani k jejím holením. Podél stěn hoří malé plameny. Světlo dopadá odněkud shora a zlatě se rozlévá po soše, zatímco hala kolem zůstává tmavá."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_TERRACOTTA_ARMY"] =
    "Řady hliněných vojáků vyplňují obraz od okraje k okraji, řada za řadou postav v životní velikosti, v pancéřových kabátech, stojících v pozoru. Ustupují do dálky v dlouhých chodbách mezi hliněnými příčkami. Každá řada mizí hlouběji v jámě, až ti nejvzdálenější jsou jen siluetami proti zlaté záři, která prosvítá vzadu v komoře. Postavy jsou hnědé jako země a šedé, ramena a přilby mají lemované teplým světlem. Nálada je tichá a nesmírná, armáda mrtvých seřazená ve tmě."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_UNITED_NATIONS"] =
    "Pohled z úrovně ulice na náměstí Organizace spojených národů. Vlevo se zvedá plochá skleněná deska věže Sekretariátu nad dlouhým nízkým obloukem budovy shromáždění. Řada stožárů nese vlajky mnoha národů podél celého bloku. Náměstí je plné delegátů: muži a ženy v business oblecích se mísí s národními kroji, uprostřed davu stojí postava v bílém zálivském rouchu a pokrývce hlavy a skupiny se cestou dovnitř zastavují v rozhovoru. Žlutý taxík čeká u obrubníku vpravo a za vlajkami se zvedá panorama New Yorku. Je pozdní odpoledne, přes dlažbu se táhnou dlouhé stíny a nízké slunce se zachytává ve skle."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_UFFIZI"] =
    "Dvě dlouhá galerijní křídla stojí proti sobě přes úzké nádvoří, vysoká renesanční průčelí ze šedého kamene a krémové omítky se sochami v nikách nad lodžií v přízemí. Nádvoří vede hluboko do obrazu k obloukovému otvoru na protějším konci a za ním se na obloze rýsuje věž. Dole je nádvoří živé Florenťany v dlouhých šatech a tmavých kabátech, sochami vystavenými na podstavcích uprostřed a stánkem s červenou stříškou postaveným vlevo v popředí. Odpolední slunce šikmo dopadá z jedné strany, horní patra hřejivě osvětluje, zatímco lodžie dole drží chladný stín."
